package com.northstarbank.console.web;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import java.nio.charset.StandardCharsets;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller @RequestMapping("/admin/audit") public class AuditController{private final AuditRepository repo;private final OutboxRepository outbox;private final AuthorizationService auth;public AuditController(AuditRepository r,OutboxRepository o,AuthorizationService a){repo=r;outbox=o;auth=a;}@GetMapping String list(Model m){auth.require("AUDIT_READ",null,false);m.addAttribute("events",repo.findTop100ByOrderByOccurredAtDesc());return"audit";}@GetMapping(value="/export.csv",produces="text/csv")ResponseEntity<byte[]> export(){auth.require("AUDIT_EXPORT",null,false);var rows=repo.findTop100ByOrderByOccurredAtDesc();StringBuilder b=new StringBuilder("timestamp,actor,action,resource,count,customer_ref,basis\n");rows.forEach(e->b.append(e.occurredAt).append(',').append(e.actor).append(',').append(e.action).append(',').append(e.resourceClass).append(',').append(e.recordCount).append(',').append(e.customerRef==null?"":e.customerRef).append(',').append(e.authorizationBasis).append('\n'));return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=audit.csv").body(b.toString().getBytes(StandardCharsets.UTF_8));}
 @GetMapping(value="/notices.csv",produces="text/csv")ResponseEntity<byte[]> notices(){auth.require("AUDIT_EXPORT",null,false);var rows=outbox.findAll();StringBuilder b=new StringBuilder("queued,recipient,subject,status,message\n");
  rows.forEach(o->b.append(o.createdAt).append(',').append(o.recipient).append(',').append(o.subject).append(',').append(o.status).append(',').append('"').append(o.body.replace("\"","\"\"")).append('"').append('\n'));
  return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=notices.csv").body(b.toString().getBytes(StandardCharsets.UTF_8));}}
